import 'package:flutter/material.dart';import '../data/app_store.dart';import '../services/operon_assistant.dart';import '../theme/operon_theme.dart';
class AiScreen extends StatefulWidget{final AppStore store;const AiScreen({super.key,required this.store});@override State<AiScreen> createState()=>_S();}
class _S extends State<AiScreen>{final q=TextEditingController();AssistantAnswer? answer;
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('OPERON Assistant')),body:Padding(padding:const EdgeInsets.all(16),child:Column(children:[const Card(child:ListTile(leading:Icon(Icons.lock,color:OperonTheme.teal),title:Text('Grounded · private-first'),subtitle:Text('Answers are assembled only from recorded OPERON data and verified knowledge. Local LLM/RAG comes later.'))),Wrap(spacing:8,children:['What should I know this shift?','P-2101A','Overdue actions'].map((x)=>ActionChip(label:Text(x),onPressed:(){q.text=x;_ask();})).toList()),const SizedBox(height:10),TextField(controller:q,onSubmitted:(_)=>_ask(),decoration:const InputDecoration(hintText:'Ask about a TAG or this shift')),const SizedBox(height:10),FilledButton.icon(onPressed:_ask,icon:const Icon(Icons.auto_awesome),label:const Text('Ask OPERON')),const SizedBox(height:16),if(answer!=null)Expanded(child:ListView(children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:SelectableText(answer!.text))),const Padding(padding:EdgeInsets.only(top:10,bottom:6),child:Text('SOURCES USED',style:TextStyle(color:OperonTheme.muted,fontSize:11,fontWeight:FontWeight.w800))),...answer!.sources.map((s)=>ListTile(dense:true,leading:const Icon(Icons.verified_outlined,color:OperonTheme.teal,size:18),title:Text(s)))]))])));
void _ask(){if(q.text.trim().isEmpty)return;setState(()=>answer=OperonAssistant(widget.store).ask(q.text.trim()));}}
